<script setup>
import { onMounted, ref } from 'vue'
import { Check, RefreshCw, Truck, X } from 'lucide-vue-next'
import { loadAdminCouriers } from '../services/adminOperationsService'
import { approveCourierApplication, listCourierApplications, rejectCourierApplication } from '../services/courierRegistrationService'
const tab = ref('PENDIENTE'); const applications = ref([]); const couriers = ref([]); const loading = ref(true); const error = ref(''); const notice = ref(''); const selected = ref(null)
async function load() { loading.value = true; error.value = ''; try { [applications.value, couriers.value] = await Promise.all([listCourierApplications(tab.value), loadAdminCouriers()]) } catch (e) { error.value = e.message || 'No se pudieron cargar las solicitudes.' } finally { loading.value = false } }
async function changeTab(value) { tab.value = value; await load() }
async function approve(item) { if (!window.confirm(`¿Aprobar la solicitud de ${item.perfiles?.nombre || 'este usuario'}?`)) return; try { await approveCourierApplication(item.id); notice.value = 'Solicitud aprobada y repartidor activado.'; selected.value = null; await load() } catch (e) { error.value = e.message || 'No se pudo aprobar la solicitud.' } }
async function reject(item) { const reason = window.prompt('Motivo del rechazo:'); if (!reason?.trim()) return; try { await rejectCourierApplication(item.id, reason.trim()); notice.value = 'Solicitud rechazada.'; selected.value = null; await load() } catch (e) { error.value = e.message || 'No se pudo rechazar la solicitud.' } }
onMounted(load)
</script>
<template><section class="admin-view"><div class="admin-view-heading"><div><span class="admin-eyebrow">OPERACIÓN</span><h2>Repartidores</h2><p>Revisa solicitudes y consulta repartidores aprobados.</p></div><button class="admin-icon-button" @click="load"><RefreshCw :size="18" /></button></div><div class="admin-tabs-inline"><button v-for="item in ['PENDIENTE','APROBADA','RECHAZADA']" :key="item" :class="{ active: tab === item }" @click="changeTab(item)">{{ item === 'PENDIENTE' ? 'Pendientes' : item === 'APROBADA' ? 'Aprobados' : 'Rechazados' }}</button></div><p v-if="error" class="admin-alert">{{ error }}</p><p v-if="notice" class="admin-success">{{ notice }}</p><div v-if="loading" class="admin-empty">Cargando solicitudes…</div><div v-else-if="!applications.length" class="admin-empty">No hay solicitudes en este estado.</div><div v-else class="admin-panel admin-table-wrap"><table class="admin-table"><thead><tr><th>Solicitante</th><th>Contacto</th><th>Vehículo</th><th>Zona</th><th>Fecha</th><th /></tr></thead><tbody><tr v-for="item in applications" :key="item.id"><td><strong>{{ item.perfiles?.nombre }}</strong></td><td>{{ item.perfiles?.telefono || '—' }}</td><td>{{ item.tipo_vehiculo }}</td><td>{{ item.zonas?.nombre }}</td><td>{{ new Date(item.solicitada_en).toLocaleDateString('es-SV') }}</td><td><button class="admin-link-button" @click="selected = item">Ver detalle</button></td></tr></tbody></table></div><div v-if="selected" class="admin-drawer-backdrop" @click.self="selected = null"><aside class="admin-order-drawer"><button class="admin-drawer-close" @click="selected = null"><X :size="20" /></button><span class="admin-eyebrow">SOLICITUD {{ selected.estado }}</span><h3>{{ selected.perfiles?.nombre }}</h3><p>{{ selected.perfiles?.telefono || 'Sin teléfono' }}</p><dl class="admin-order-meta"><div><dt>Zona</dt><dd>{{ selected.zonas?.nombre }}</dd></div><div><dt>Vehículo</dt><dd>{{ selected.tipo_vehiculo }}</dd></div><div v-if="selected.motivo_rechazo"><dt>Motivo</dt><dd>{{ selected.motivo_rechazo }}</dd></div></dl><div v-if="selected.estado === 'PENDIENTE'" class="admin-order-actions"><button @click="approve(selected)"><Check :size="17" /> Aprobar solicitud</button><button @click="reject(selected)"><X :size="17" /> Rechazar solicitud</button></div></aside></div><div class="admin-list admin-courier-list"><h3>Repartidores registrados</h3><div v-if="!couriers.length" class="admin-empty">No hay repartidores registrados.</div><div v-for="courier in couriers" v-else :key="courier.id" class="admin-courier-row"><Truck :size="19" /><span><strong>{{ courier.perfiles?.nombre || 'Sin nombre' }}</strong><small>{{ courier.zonas?.nombre || 'Sin zona' }}</small></span><b>{{ courier.disponible && courier.activo ? 'Disponible' : 'No disponible' }}</b></div></div></section></template>
